                        {% endif %}
                        {% if shipping_address.address_line2 %}
                            <div class="address-line">{{ shipping_address.address_line2 }}</div>
                        {% endif %}
                        <div class="address-line">
                            {% if shipping_address.city %}{{ shipping_address.city }}{% endif %}
                            {% if shipping_address.state and shipping_address.city %}, {% endif %}
                            {% if shipping_address.state %}{{ shipping_address.state }}{% endif %}
                        </div>
                        <div class="address-line">
                            {% if shipping_address.pincode %}C.P. {{ shipping_address.pincode }}{% endif %}
                            {% if shipping_address.country and shipping_address.pincode %}, {% endif %}
                            {% if shipping_address.country %}{{ shipping_address.country }}{% endif %}
                        </div>
                        {% if shipping_address.phone or shipping_address.email_id %}
                            <div class="address-line" style="margin-top: 5px;">
                                {% if shipping_address.phone %}<strong>Teléfono:</strong> {{ shipping_address.phone }}<br>{% endif %}
                                {% if shipping_address.email_id %}<strong>Correo:</strong> {{ shipping_address.email_id }}{% endif %}
                            </div>
                        {% endif %}
                    </div>
                {% endif %}

                {% if doc.contact_display %}
                    <div class="info-line"><strong>Contacto:</strong> {{ doc.contact_display }}</div>
                {% endif %}
            </td>

            <td class="delivery-details">
                <span class="section-title">Dirección de Facturación</span>
                {% if doc.customer_address %}
                    {% set billing_address = frappe.get_doc("Address", doc.customer_address) %}
                    {% if billing_address.address_line1 %}
                        <div class="info-line">{{ billing_address.address_line1 }}</div>
                    {% endif %}
                    {% if billing_address.address_line2 %}
                        <div class="info-line">{{ billing_address.address_line2 }}</div>
                    {% endif %}
                    {% if billing_address.city %}
                        <div class="info-line">{{ billing_address.city }}</div>
                    {% endif %}
                    {% if billing_address.state %}
                        <div class="info-line">{{ billing_address.state }} {% if billing_address.pincode %}{{ billing_address.pincode }}{% endif %}</div>
                    {% endif %}
                    {% if billing_address.country %}
                        <div class="info-line">{{ billing_address.country }}</div>
                    {% endif %}
                    {% if billing_address.phone %}
                        <div class="info-line" style="margin-top: 8px;"><strong>Tel:</strong> {{ billing_address.phone }}</div>
                    {% endif %}
                    {% if billing_address.email_id %}
                        <div class="info-line"><strong>Email:</strong> {{ billing_address.email_id }}</div>
                    {% endif %}
                {% endif %}
            </td>
        </tr>
    </table>

    <!-- TABLA DE PRODUCTOS -->
    <table class="table items-table">
        <thead>
            <tr>
                <th class="text-center" width="5%">Sr</th>
                <th width="12%">Código</th>
                <th width="28%">Descripción</th>
                <th class="text-center" width="10%">Imagen</th>
                <th class="text-right" width="8%">Cantidad</th>
                <th class="text-center" width="7%">UOM</th>
                <th class="text-right" width="10%">Precio</th>
                <th class="text-right" width="10%">Importe</th>
                <th class="text-right" width="10%">Peso Total</th>
            </tr>
        </thead>
        <tbody>
            {% for row in doc.items %}
            <tr>
                <td class="text-center">{{ row.idx }}</td>
                <td>
                    <div class="item-code">{{ row.item_code }}</div>
                </td>
                <td>
                    {% if row.item_name %}
                        <strong class="item-title">{{ row.item_name }}</strong>
                    {% endif %}
                    {% if row.description %}
                        <div class="item-description">{{ row.description }}</div>
                    {% endif %}
                </td>
                <td class="text-center item-image-cell">
                    {% if row.image %}
                        <img src="{{ row.image }}" alt="Img" class="item-image" />
                    {% else %}
                        -
                    {% endif %}
                </td>
                <td class="text-right">{{ row.qty }}</td>
                <td class="text-center">{{ row.uom or row.stock_uom or "Nos." }}</td>
                <td class="text-right">{{ row.get_formatted("rate", doc) or frappe.format_currency(row.rate, doc.currency) }}</td>
                <td class="text-right"><strong>{{ row.get_formatted("amount", doc) or frappe.format_currency(row.amount, doc.currency) }}</strong></td>
                <td class="text-right">{{ row.total_weight or 0 }}</td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    <!-- TOTALES -->
    <div class="totals-section">
        <table class="totals-table">
            <tr>
                <td class="total-label">Cantidad total:</td>
                <td class="total-value">{{ doc.total_qty or 0 }}</td>
            </tr>
            <tr>
                <td class="total-label">Total:</td>
                <td class="total-value">{{ doc.get_formatted("base_total") or frappe.format_currency(doc.base_total, doc.currency) }}</td>
            </tr>
            {% for tax in doc.taxes %}
            <tr>
                <td class="total-label">{{ tax.description or tax.account_head }}:</td>
                <td class="total-value">{{ tax.get_formatted("tax_amount", doc) or frappe.format_currency(tax.tax_amount, doc.currency) }}</td>
            </tr>
            {% endfor %}
            <tr class="grand-total-row">
                <td class="total-label big-label">TOTAL:</td>
                <td class="total-value big-value">{{ doc.get_formatted("grand_total") or frappe.format_currency(doc.grand_total, doc.currency) }}</td>
            </tr>
        </table>
        <div style="clear: both;"></div>

        {% if doc.in_words %}
        <div class="total-in-words">
            <strong>En palabras:</strong> {{ doc.in_words }}
        </div>
        {% endif %}
    </div>

    <!-- TÉRMINOS Y CONDICIONES -->
    {% if doc.terms %}
    <div class="terms">
        <span class="terms-title">Términos y Condiciones:</span>
        <div class="terms-content">{{ doc.terms }}</div>
    </div>
    {% endif %}

    <!-- SECCIÓN DE FIRMAS -->
    <div class="signature-section">
        <div class="signature-box">
            <div class="signature-line"></div>
            <div class="signature-label">Firma del Cliente</div>
